head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[image > M > setLongdesc]<br/>Image 컴포넌트의 longdesc 속성을 설정합니다.",
    "validation" : [
        "Url(필수) 파라미터로 Image 컴포넌트에 로드된 이미지의 상세 설명 페이지를 URL 로 설정합니다.",
        "HTML5 미지원 속성으로 alt, ariaLabel, title 등의 속성 사용을 권장합니다.",
    ]
}



scwin.onpageload = function () {
    // 정적 select1 초기값 설정 (Url 파라미터 : 별도 페이지 URL)
    par_Url.setValue("/sample/image/image_longdesc.html");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[현재] target1 은 longdesc 를 선언하지 않은 상태로 생성됩니다\n[절차] Url 파라미터 선택 -> setLongdesc 버튼 클릭 (초기 상태로 되돌리려면 Target 재생성)\n[확인] 호출 전 후의 마크업 longdesc 속성값과 getLongdesc() 반환값, 화면 변화를 함께 확인합니다"', '', 'label1');

    // longdesc 는 선언하지 않고 setLongdesc 호출로만 설정한다
    await $c.gcm.createBasicImage('', '');
}



// setLongdesc 호출 및 validation 항목별 판정 출력
scwin.btn_setLongdesc_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    let img = target1.render;

    // 호출 전 상태 (초기 생성 시 longdesc 미설정)
    let beforeAttr = img.getAttribute("longdesc");
    let beforeGet  = target1.getLongdesc();
    let beforeBox  = img.offsetWidth + " x " + img.offsetHeight;

    let pUrl = par_Url.getValue();

    // Url(필수) 파라미터로 상세 설명 페이지 URL 설정
    target1.setLongdesc(pUrl);

    let afterAttr = img.getAttribute("longdesc");
    let afterGet  = target1.getLongdesc();

    let strBefore = (beforeAttr === null) ? "없음 (longdesc 속성 미출력)" : "'" + beforeAttr + "'";
    let strAfter  = (afterAttr  === null) ? "없음 (longdesc 속성 미출력)" : "'" + afterAttr + "'";

    // 접근성 이름은 alt, ariaLabel, title 로만 결정되며 longdesc 는 이름 소스가 아니다
    let accSrc = [];

    if (img.getAttribute("aria-label")) accSrc.push("ariaLabel");
    if (img.getAttribute("alt"))        accSrc.push("alt");
    if (img.getAttribute("title"))      accSrc.push("title");

    let strAccSrc = (accSrc.length === 0) ? "없음 (alt, ariaLabel, title 모두 미설정)" : accSrc.join(", ");

    // 상세 설명으로 이동할 수 있는 UI 노드가 렌더되는지 확인
    let ldUiCnt = img.parentElement.querySelectorAll("a, [role='link'], [class*='longdesc']").length;

    bottom.setReturnValue("[1] setLongdesc('" + pUrl + "') 호출 -> 마크업 longdesc : " + strAfter + " (호출 전 : " + strBefore + ") / getLongdesc() : '" + afterGet + "' (호출 전 : '" + beforeGet + "')");
    bottom.setReturnValue("[2] 접근성 이름 소스 : " + strAccSrc + " / 상세 설명 UI 노드 " + ldUiCnt + "개 / 렌더 영역 " + img.offsetWidth + " x " + img.offsetHeight + " (호출 전 " + beforeBox + ")");
};
